import json

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + '...[TRUNC]'

with open('convlog-issue-113.jsonl') as f:
    for i, line in enumerate(f, 1):
        line = line.strip()
        if not line: continue
        d = json.loads(line)
        t = d.get('type')
        ts = d.get('timestamp','')
        if t == 'user' or t == 'assistant':
            msg = d.get('message', {})
            role = msg.get('role')
            content = msg.get('content')
            if isinstance(content, str):
                print(f'{i}|{ts}|{t}|{role}|TEXT|{trunc(content)}')
            elif isinstance(content, list):
                for c in content:
                    ctype = c.get('type')
                    if ctype == 'text':
                        print(f'{i}|{ts}|{t}|{role}|TEXT|{trunc(c.get(\"text\"))}')
                    elif ctype == 'tool_use':
                        print(f'{i}|{ts}|{t}|{role}|TOOL_USE|{c.get(\"name\")}|{trunc(c.get(\"input\"))}')
                    elif ctype == 'tool_result':
                        cont = c.get('content')
                        print(f'{i}|{ts}|{t}|{role}|TOOL_RESULT|{trunc(cont)}')
                    else:
                        print(f'{i}|{ts}|{t}|{role}|OTHER:{ctype}')
        else:
            print(f'{i}|{ts}|{t}|META')
" > summary.txt
